import{_ as t,c as a,o,ae as r}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse('{"title":"Cart Rule Coupons","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/marketing/promotions/cart-rule-coupons/index.md","filePath":"api/graphql-api/admin/marketing/promotions/cart-rule-coupons/index.md"}'),n={name:"api/graphql-api/admin/marketing/promotions/cart-rule-coupons/index.md"};function i(s,e,c,d,p,l){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="cart-rule-coupons" tabindex="-1">Cart Rule Coupons <a class="header-anchor" href="#cart-rule-coupons" aria-label="Permalink to &quot;Cart Rule Coupons&quot;">​</a></h1><p>A <strong>cart rule coupon</strong> is a coupon code that activates a coupon-gated cart rule. It mirrors the coupon table on the admin <strong>Marketing → Promotions → Cart Rules → Coupons</strong> screen, which sits inside a single cart rule.</p><h2 id="how-cart-rule-coupons-work" tabindex="-1">How cart rule coupons work <a class="header-anchor" href="#how-cart-rule-coupons-work" aria-label="Permalink to &quot;How cart rule coupons work&quot;">​</a></h2><p>A cart rule can be set to apply automatically or only when a shopper enters a coupon code (<code>couponType</code> <code>1</code> on the parent rule). When the rule is coupon-gated, these codes are what the shopper types at checkout to unlock the discount.</p><ul><li><strong>One rule, many codes.</strong> Every coupon belongs to exactly one cart rule. The list is always scoped to a <code>cartRuleId</code>, and codes from one rule never appear under another.</li><li><strong>Primary vs. secondary.</strong> Each coupon has an <code>isPrimary</code> flag. The rule&#39;s single <strong>primary</strong> code is managed on the cart rule itself. The codes you create or generate here are <strong>secondary</strong> codes (<code>isPrimary</code> is <code>false</code>, <code>type</code> is <code>1</code>) — useful for handing out many distinct codes for the same promotion.</li><li><strong>Two ways to add codes.</strong> <a href="/api/graphql-api/admin/marketing/promotions/cart-rule-coupons-create.html">Create</a> adds one explicit code; <a href="/api/graphql-api/admin/marketing/promotions/cart-rule-coupons-generate.html">Generate</a> bulk-creates many random codes from a length, format, prefix and suffix.</li><li><strong>Usage limits.</strong> <code>usageLimit</code> caps total redemptions and <code>usagePerCustomer</code> caps per-customer redemptions. <code>timesUsed</code> is read-only and counts how often the code has been redeemed. <code>expiredAt</code> sets an expiry date. When omitted on create, these inherit the parent rule&#39;s values.</li></ul><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/marketing/promotions/cart-rule-coupons-list.html">List</a></td><td><code>adminMarketingCartRuleCoupons</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/promotions/cart-rule-coupons-create.html">Create</a></td><td><code>createAdminMarketingCartRuleCoupon</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/promotions/cart-rule-coupons-generate.html">Generate</a></td><td><code>createAdminMarketingCartRuleCouponGenerate</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/promotions/cart-rule-coupons-delete.html">Delete</a></td><td><code>deleteAdminMarketingCartRuleCoupon</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/promotions/cart-rule-coupons-mass-delete.html">Mass Delete</a></td><td><code>createAdminMarketingCartRuleCouponMassDelete</code> mutation</td></tr></tbody></table><p>This is a sub-resource of <a href="/api/graphql-api/admin/marketing/promotions/cart-rules/">Cart Rules</a> — every coupon belongs to one cart rule, and the list requires its <code>cartRuleId</code>.</p><p>All Cart Rule Coupons operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',9)]))}const m=t(n,[["render",i]]);export{h as __pageData,m as default};
